export interface StartConversationOptions {
    /** Skip the built-in haircheck because the host has already selected its media devices. */
    haircheck?: "provided";
    devices?: {
        microphone?: {
            deviceId?: string;
            enabled?: boolean;
            track?: MediaStreamTrack;
        };
        camera?: {
            deviceId?: string;
            enabled?: boolean;
            track?: MediaStreamTrack;
        };
    };
}
